  const negative = x < 0;
  const text = String(Math.abs(x)).split("").reverse().join("");
  let value = Number(text);
  if (negative) value = -value;
  if (value < -2147483648 || value > 2147483647) return 0;
  return value;
}

function solve(x) {
  let rev = 0;
  let n = x < 0 ? -x : x;
  while (n > 0) {
    rev = rev * 10 + (n % 10);
    n = Math.floor(n / 10);
  }
  if (rev > 2147483647) return 0;
  return x < 0 ? -rev : rev;
}
